(() => {
 'use strict';
 const framed=window!==window.parent&&new URL(location.href).searchParams.has('nk_frame');
 if(!document.documentElement.dataset.nkRouteDocument&&!framed&&!new URL(location.href).searchParams.has('nk_direct'))return;
 const root=document.querySelector('.landing-page .hero');if(!root)return;
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const ease='cubic-bezier(.22,1,.36,1)',clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
 let lenis;if(!reduce&&window.Lenis)lenis=new Lenis({duration:1.4,lerp:undefined,smoothWheel:true,syncTouch:false,autoRaf:true,anchors:false,prevent:node=>!!node.closest?.('.section-map,.brand-dialog,.menu-overlay')});
 if(lenis){document.addEventListener('noklith:overlaychange',()=>document.body.classList.contains('map-open')||document.querySelector('dialog[open]')?lenis.stop():lenis.start());addEventListener('pagehide',()=>lenis.destroy(),{once:true})}
 function appear(selector,{y=40,duration=1000,threshold=.2,stagger=0}={}){
  const nodes=$$(selector);if(reduce)return;
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;observer.unobserve(e.target);e.target.animate([{opacity:0,transform:'translateY('+y+'px)'},{opacity:1,transform:'translateY(0)'}],{duration,delay:Number(e.target.dataset.refDelay||0),easing:ease,fill:'backwards'})}),{threshold});
  nodes.forEach((e,i)=>{e.dataset.refDelay=String((i%3)*stagger);observer.observe(e)})
 }
 function words(element,initialDelay=100,stagger=30){
  if(!element||reduce)return;const label=element.textContent;element.setAttribute('aria-label',label);
  const walker=document.createTreeWalker(element,NodeFilter.SHOW_TEXT),texts=[];while(walker.nextNode())if(walker.currentNode.parentElement.tagName!=='SUP')texts.push(walker.currentNode);
  const spans=[];texts.forEach(n=>{const f=document.createDocumentFragment();n.textContent.split(/(\s+)/).forEach(w=>{if(!w.trim())f.append(document.createTextNode(w));else{const s=document.createElement('span');s.className='reference-word';s.textContent=w;s.setAttribute('aria-hidden','true');f.append(s);spans.push(s)}});n.replaceWith(f)});
  const play=()=>spans.forEach((s,i)=>s.animate([{opacity:.001,filter:'blur(6px)',transform:'translateY(12px)'},{opacity:1,filter:'blur(0px)',transform:'translateY(0)'}],{duration:900,delay:initialDelay+i*stagger,easing:ease,fill:'backwards'}));
  return play;
 }
 $$('.statement').forEach(e=>{const play=words(e);if(!play)return;const observer=new IntersectionObserver(items=>{if(items.some(i=>i.isIntersecting)){play();observer.disconnect()}},{threshold:.3});observer.observe(e)});
 appear('.section-label',{y:0,duration:800,threshold:.5});appear('.reference-network-strip>div',{y:20,duration:900,threshold:.5,stagger:60});appear('.reference-about-images>figure',{y:60,duration:1200,stagger:100});appear('.reference-foundation-rows article,.reference-stat-grid article,.reference-account-grid>*',{stagger:100});appear('.reference-signature',{y:20,duration:1000});appear('.reference-process-hero',{y:60,duration:1200});appear('.process-row',{y:30,duration:1000,threshold:.3});appear('.note',{stagger:100});appear('.pledges-layout',{stagger:100});
 const introWords=words($('.hero-intro'),2150,12);introWords?.();
 const copy=$('#value-copy'),valueBox=$('.hero-values'),controls=$$('.value-controls button');let valueElapsed=0,valueStage=0,valueHover=false;
 const progress=document.createElement('i');progress.className='reference-value-progress';$('.value-controls')?.append(progress);
 const animateValue=()=>{valueStage=Number($('#value-index')?.textContent||1)-1;valueElapsed=0;progress.getAnimations().forEach(a=>a.cancel());if(!reduce)progress.animate([{scale:'0 1'},{scale:'1 1'}],{duration:6000,delay:350,easing:'cubic-bezier(.25,.6,.4,1)',fill:'both'});if(!reduce)copy.querySelectorAll('.value-title,p').forEach((e,i)=>e.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:800,delay:350+i*150,easing:ease,fill:'backwards'}))};
 copy?.addEventListener('valuechange',animateValue);animateValue();valueBox?.addEventListener('mouseenter',()=>{valueHover=true;progress.getAnimations().forEach(a=>a.pause())});valueBox?.addEventListener('mouseleave',()=>{valueHover=false;progress.getAnimations().forEach(a=>a.play())});
 const features=$$('.feature-stack .feature'),stack=$('.feature-stack');if(!reduce)stack.classList.add('is-pinned');let currentFeature=-1,oldTimer;
 const featureWordPlayers=features.map(e=>words(e.querySelector('h2'),290,22));
 function feature(n){if(n===currentFeature)return;const previous=features[currentFeature];clearTimeout(oldTimer);features.forEach(e=>{e.classList.remove('is-active','is-previous');e.inert=true});if(previous)previous.classList.add('is-previous');features[n].classList.add('is-active');features[n].inert=false;currentFeature=n;featureWordPlayers[n]?.();oldTimer=setTimeout(()=>previous?.classList.remove('is-previous'),1400);stack.dataset.activeFeature=String(n)}
 if(reduce)features.forEach(e=>{e.inert=false;e.classList.add('is-active')});
 const tiles=$$('.reference-tile'),field=$('.reference-image-field');let fieldVisible=false,direction=1,boost=0,lastScroll=scrollY,lastTime=0,frame;
 const tileSpec=tiles.map((e,i)=>{const depth=(i%5)/4,size=50+((i*37)%81),x=(i*37+8)%95,y=((i*127)%1000)/1000;const t={e,depth,size,x,y,speed:(100+(i*29)%101)*(1-depth*.3),scale:.55};e.style.setProperty('--tile-size',size+'px');e.style.setProperty('--tile-x',x+'%');e.style.setProperty('--tile-top',(y*100)+'%');e.style.opacity=String(1-.45*depth);e.style.zIndex=String(Math.round((1-depth)*10));return t});
 if(field)new IntersectionObserver(es=>{fieldVisible=es[0].isIntersecting},{threshold:0}).observe(field);
 $$('.reference-stat-grid [data-count]').forEach(e=>{const target=Number(e.dataset.count);if(reduce)return;const observer=new IntersectionObserver(es=>{if(!es[0].isIntersecting)return;observer.disconnect();let start;const tick=t=>{if(!start)start=t+200;const p=clamp((t-start)/1600);e.textContent=String(Math.round(target*(p===1?1:1-2**(-10*p)))).padStart(2,'0');if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)},{threshold:.5});observer.observe(e)});
 const motto=$('.reference-motto');if(motto&&!reduce)new IntersectionObserver(es=>{const on=es[0].isIntersecting,phrases=[...motto.querySelectorAll('h2')],before=phrases.map(p=>p.getBoundingClientRect());motto.classList.toggle('is-spread',on);phrases.forEach((p,i)=>{const after=p.getBoundingClientRect();p.animate([{transform:'translate('+(before[i].x-after.x)+'px,'+(before[i].y-after.y)+'px)'},{transform:'none'}],{duration:800,easing:'cubic-bezier(.65,0,.35,1)'})});motto.querySelector('span').animate(on?[{opacity:0,transform:'translateY(40px)'},{opacity:.5,transform:'none'}]:[{opacity:.5},{opacity:0}],{duration:900,delay:on?600:0,easing:ease,fill:'forwards'})},{threshold:.5}).observe(motto);
 const tabs=$$('[data-system]');tabs.forEach(b=>{b.addEventListener('click',()=>{if(!reduce)$$('.system-panel-inner>*').forEach((e,i)=>e.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:900,delay:i*80,easing:ease,fill:'backwards'}))});if(matchMedia('(pointer:fine)').matches)b.addEventListener('mouseenter',()=>{if(b.getAttribute('aria-selected')!=='true')b.click()})});
 const slides=$$('.pledge-slide');let pledge=0;function showPledge(n){pledge=(n+slides.length)%slides.length;slides.forEach((e,i)=>{e.setAttribute('aria-hidden',String(i!==pledge));e.inert=i!==pledge});$('#pledge-count').textContent=String(pledge+1).padStart(2,'0');if(innerWidth<1440)requestAnimationFrame(()=>{const active=slides[pledge],height=active.querySelector('.reference-quote-copy').scrollHeight+active.querySelector('.reference-quote-art').getBoundingClientRect().height;$('#pledge-window').style.height=Math.ceil(height)+'px'});else $('#pledge-window').style.height='460px'};addEventListener('resize',()=>{if(slides.length)showPledge(pledge)});if(slides.length){$('#pledge-prev').onclick=()=>showPledge(pledge-1);$('#pledge-next').onclick=()=>showPledge(pledge+1);showPledge(0)}
 $$('.faq-list details').forEach(d=>{const summary=d.querySelector('summary'),answer=d.querySelector('p');if(!answer)return;const wrap=document.createElement('div');wrap.className='reference-answer';answer.before(wrap);wrap.append(answer);let animation;
  summary.addEventListener('click',e=>{e.preventDefault();if(animation)return;const opening=!d.open;if(opening)d.open=true;const h=wrap.getBoundingClientRect().height;animation=wrap.animate(opening?[{height:'0px',opacity:0},{height:h+'px',opacity:1}]:[{height:h+'px',opacity:1},{height:'0px',opacity:0}],{duration:reduce?0:400,easing:'cubic-bezier(.4,0,.2,1)'});animation.finished.then(()=>{if(!opening)d.open=false;animation=null})})
 });
 const footer=$('.footer-word');if(footer&&!reduce){const text=footer.textContent;footer.textContent='';[...text].forEach((c,i)=>{const glyph=document.createElement('span');glyph.className='reference-footer-glyph';glyph.textContent=c;for(let band=0;band<6;band++){const s=document.createElement('i');s.textContent=c;s.className='reference-footer-band';s.style.clipPath='inset('+(band*16.6667-.3)+'% -20% '+(100-(band+1)*16.6667-.3)+'% -20%)';s.dataset.band=String(band);s.dataset.char=String(i);glyph.append(s)}footer.append(glyph)});new IntersectionObserver((es,o)=>{if(!es[0].isIntersecting)return;o.disconnect();footer.querySelectorAll('i').forEach(s=>{const b=Number(s.dataset.band),i=Number(s.dataset.char);s.animate([{opacity:0,transform:'translateX('+((b+i)%2?45:-45)+'%)'},{opacity:1,transform:'none'}],{duration:700,delay:100+i*50+b*25,easing:'cubic-bezier(.19,1,.22,1)',fill:'backwards'})})},{threshold:.35}).observe(footer)}
 function update(time){const dt=Math.min(.05,(time-lastTime)/1000||.016);lastTime=time;
  if(!reduce&&!document.hidden){
   if(fieldVisible){const h=field.offsetHeight;boost*=Math.exp(-7*dt);tileSpec.forEach((t,i)=>{if(innerWidth<810&&i>=12){t.e.hidden=true;return}t.e.hidden=false;t.y+=direction*(t.speed+boost)*dt/h;if(t.y>1.15)t.y=-.13;if(t.y<-.15)t.y=1.13;t.scale+=(.55+clamp(t.y)*.75-t.scale)*(1-Math.exp(-14*dt));t.e.style.transform='translateY('+((t.y*h)-(Number(t.e.style.getPropertyValue('--tile-top').replace('%',''))/100*h))+'px) scale('+t.scale+')'})}
   const r=stack.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight*.7)feature(Math.min(2,Math.floor(clamp(-r.top/(r.height-innerHeight))*3)));
   const hr=root.getBoundingClientRect();if(hr.bottom>0&&!valueHover){valueElapsed+=dt;if(valueElapsed>=6){valueStage=(valueStage+1)%controls.length;controls[valueStage]?.click()}}
   const closing=$('.closing'),cr=closing.getBoundingClientRect();if(cr.bottom>0&&cr.top<innerHeight)closing.style.setProperty('--closing-parallax',(clamp((innerHeight-cr.top)/(innerHeight+cr.height))*300-150)+'px');
   const fv=$('.reference-footer-visual');if(fv){const fr=fv.getBoundingClientRect();if(fr.bottom>0&&fr.top<innerHeight)fv.style.setProperty('--footer-image-scale',String(.8+clamp((innerHeight-fr.top)/(innerHeight+fr.height))*.2))}
  }frame=requestAnimationFrame(update)
 }
 addEventListener('scroll',()=>{const delta=scrollY-lastScroll;if(Math.abs(delta)>1){direction=delta>0?-1:1;boost=Math.min(260,boost+Math.min(Math.abs(delta)*.7,220))}lastScroll=scrollY},{passive:true});
 if(!reduce)frame=requestAnimationFrame(update);addEventListener('pagehide',()=>cancelAnimationFrame(frame),{once:true});document.addEventListener('noklith:suspend',()=>{cancelAnimationFrame(frame);lenis?.stop()},{once:true});
})();
